package main

import (
	"bufio"
	"fmt"
	"os"
)

// ここに greet(name string) string を書く:
// 「こんにちは、<名前> さん」という文字列を返す

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Scan()
	name := sc.Text()

	// ここから下を書く: greet を呼んで結果を出力する
	_ = name
	_ = fmt.Println
}

exercise.answer:
// lesson23 ch01 解答
package main

import (
	"bufio"
	"fmt"
	"os"
)

// main 以外の関数は入口にならず、main から呼ばれてはじめて動きます。
// そのため Python のような if __name__ == "__main__": ガードは不要です。
func greet(name string) string {
	return "こんにちは、" + name + " さん"
}

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Scan()
	name := sc.Text()

	// 実行は常に main から始まる、が Go の決まりです
	fmt.Println(greet(name))
}
